using System;
using System.Collections.Generic;
using System.Linq;
using SeongbukAR.Notes;
using SeongbukAR.Scanning;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.XR.ARFoundation;

namespace SeongbukAR
{
    public sealed class GuideApp : MonoBehaviour
    {
        // Kept serialized so scenes generated by the earlier starter still work.
        public bool editorPreview;
        public WasteItem CurrentItem { get; private set; }
        public GuideNode CurrentNode { get; private set; }
        public string TrackingMessage { get; set; }

        enum Page { Home, Search, Scanning, Candidates, Guide, Placement, Message, Notes, NoteEdit, NoteDetail }
        Page _page;
        WasteCatalog _catalog;
        GuideUi _ui;
        WasteScanController _scanner;
        SpatialGuide _spatial;
        PersonalWasteNotes _notes;
        PersonalWasteNote _noteDraft;
        string _notesLoadError;
        string _selectedNoteId;
        string _noteQuery = "";
        bool _confirmNoteDelete;
        RectTransform _noteResults;
        Text _noteFormError;
        readonly Stack<GuideNode> _history = new Stack<GuideNode>();
        RecognitionCandidate[] _candidates = Array.Empty<RecognitionCandidate>();
        RectTransform _searchResults;
        string _query = "";
        string _category = "전체";
        string _error;
        string _notice;
        string _messageTitle;
        string _messageBody;
        bool _acceptScanResult;
        bool _cameFromScan;
        bool _started;
        bool _placementPlaced;

        bool CanScan => _scanner != null && _scanner.IsSupported;

        void Awake()
        {
            Application.targetFrameRate = 60;
            _ui = new GuideUi(transform);
            try
            {
                var json = Resources.Load<TextAsset>("Data/seongbuk-demo");
                if (json == null) throw new InvalidOperationException("품목 목록 파일을 찾을 수 없습니다.");
                _catalog = new WasteCatalog(JsonUtility.FromJson<WasteCatalogData>(json.text));
            }
            catch (Exception exception)
            {
                _error = exception.Message;
                Debug.LogException(exception);
            }
            try { _notes = new PersonalWasteNotes(PersonalWasteNoteStore.Load()); }
            catch (Exception exception)
            {
                // Keep the built-in guide usable and preserve the existing file.
                _notesLoadError = "기존 메모를 읽을 수 없습니다. 저장된 내용을 보호하기 위해 새 메모 저장을 중지했습니다. 앱을 다시 실행해 주세요.";
                Debug.LogWarning("Personal waste notes could not load: " + exception.Message);
            }
        }

        void Start()
        {
            // Old generated scenes may still contain card tracking and a mascot.
            // Real-object scanning is now the default interaction.
            foreach (var tracker in FindObjectsByType<CardGuideTracker>(FindObjectsSortMode.None))
            {
                tracker.enabled = false;
                var imageManager = tracker.GetComponent<ARTrackedImageManager>();
                if (imageManager != null) imageManager.enabled = false;
            }

            var cameraManager = FindAnyObjectByType<ARCameraManager>();
            if (!editorPreview && cameraManager != null)
            {
                cameraManager.autoFocusRequested = true;
                _scanner = GetComponent<WasteScanController>();
                if (_scanner == null) _scanner = gameObject.AddComponent<WasteScanController>();
                _scanner.cameraManager = cameraManager;
                _scanner.Completed += ScanCompleted;
                _spatial = GetComponent<SpatialGuide>();
                if (_spatial == null) _spatial = gameObject.AddComponent<SpatialGuide>();
                _spatial.Configure(cameraManager.GetComponent<Camera>(), _ui.Regular, _ui.Semibold);
            }
            _started = true;
            ShowHome();
        }

        void Update() => _ui?.UpdateSafeArea();

        void OnEnable()
        {
            _ui?.SetVisible(true);
            if (_started) Render();
        }

        void OnDisable()
        {
            GuideUi.DismissKeyboard();
            _ui?.SetVisible(false);
            _acceptScanResult = false;
            _scanner?.CancelScan();
            _spatial?.Clear();
            if (_page == Page.Scanning) _page = Page.Home;
        }

        void OnDestroy()
        {
            if (_scanner != null)
            {
                _scanner.Completed -= ScanCompleted;
                _scanner.CancelScan();
            }
        }

        void Navigate(Page page)
        {
            GuideUi.DismissKeyboard();
            if (page != Page.Scanning)
            {
                _acceptScanResult = false;
                _scanner?.CancelScan();
            }
            if (page != Page.Guide) _spatial?.Clear();
            _notice = null;
            _page = page;
            Render();
        }

        void ShowHome()
        {
            CurrentItem = null;
            CurrentNode = null;
            _history.Clear();
            Navigate(Page.Home);
        }

        void ShowSearch(string query = null)
        {
            if (query != null) { _query = query; _category = "전체"; }
            CurrentItem = null;
            CurrentNode = null;
            _history.Clear();
            Navigate(Page.Search);
        }

        // Retained for existing components; continuous tracking must not reset
        // answers. A deliberate scan confirmation uses SelectItem(restart:true).
        public bool OpenItem(string id) => SelectItem(id, false, false);

        bool SelectItem(string id, bool restart, bool fromScan)
        {
            var item = _catalog?.Find(id);
            if (item == null) return false;
            if (!restart && CurrentItem == item) return true;
            CurrentItem = item;
            CurrentNode = item.FindNode(item.startNodeId);
            _history.Clear();
            _cameFromScan = fromScan;
            _spatial?.Clear();
            Navigate(Page.Guide);
            return true;
        }

        void Choose(GuideChoice choice)
        {
            var next = CurrentItem.FindNode(choice.nextNodeId);
            if (next == null) return;
            _history.Push(CurrentNode);
            CurrentNode = next;
            _notice = null;
            _spatial?.Clear();
            Render();
        }

        void BackFromGuide()
        {
            _spatial?.Clear();
            _notice = null;
            if (_history.Count > 0)
            {
                CurrentNode = _history.Pop();
                Render();
            }
            else if (_cameFromScan) Navigate(Page.Candidates);
            else ShowSearch();
        }

        void StartScan()
        {
            if (!CanScan)
            {
                ShowMessage("아이폰·아이패드에서 스캔하세요",
                    "실물 스캔은 아이폰·아이패드에 앱을 설치한 뒤 사용할 수 있습니다. 맥북에서는 이름 검색과 배출 안내를 확인하세요.");
                return;
            }
            if (_scanner.IsBusy) return;
            _spatial?.Clear();
            _acceptScanResult = true;
            if (!_scanner.RequestScan())
            {
                _acceptScanResult = false;
                ShowMessage("카메라를 확인해 주세요", _scanner.Status);
                return;
            }
            _page = Page.Scanning;
            Render();
        }

        void ScanCompleted(ScanResponse response)
        {
            if (!_acceptScanResult || _page != Page.Scanning) return;
            _acceptScanResult = false;
            if (!response.success)
            {
                ShowMessage("사진을 확인할 수 없습니다",
                    "밝은 곳에서 물건 하나를 가까이 비춘 뒤 다시 촬영하세요. 이름으로 직접 찾을 수도 있습니다.");
                return;
            }
            var signals = response.labels.Select(label => new RecognitionSignal
                { identifier = label.identifier, confidence = label.confidence });
            _candidates = WasteRecognition.Match(_catalog, signals);
            Debug.Log("Waste scan labels: " + string.Join(", ", response.labels.Select(label =>
                label.identifier + "=" + label.confidence.ToString("0.000", System.Globalization.CultureInfo.InvariantCulture))) +
                "; candidates: " + string.Join(", ", _candidates.Select(candidate => candidate.item.id)));
            if (_candidates.Length == 0)
            {
                ShowMessage("일치하는 물건을 찾지 못했습니다",
                    "물건 하나를 가운데 놓고 다른 각도에서 다시 촬영하세요. 작은 물건이나 재질 구분이 어려운 물건은 이름으로 찾아보세요.");
                return;
            }
            Navigate(Page.Candidates);
        }

        void ShowMessage(string title, string body)
        {
            _messageTitle = title;
            _messageBody = body;
            Navigate(Page.Message);
        }

        void Render()
        {
            if (_ui == null) return;
            if (_error != null)
            {
                var errorPage = _ui.Begin();
                _ui.Header(errorPage, "어디다 버려?");
                _ui.Label(errorPage, "품목 목록을 불러올 수 없습니다", 24, true);
                _ui.Label(errorPage, _error, 15, false, GuideUi.Muted);
                return;
            }
            switch (_page)
            {
                case Page.Home: RenderHome(); break;
                case Page.Search: RenderSearch(); break;
                case Page.Scanning: RenderScanning(); break;
                case Page.Candidates: RenderCandidates(); break;
                case Page.Guide: RenderGuide(); break;
                case Page.Placement: RenderPlacement(); break;
                case Page.Message: RenderMessage(); break;
                case Page.Notes: RenderNotes(); break;
                case Page.NoteEdit: RenderNoteEdit(); break;
                case Page.NoteDetail: RenderNoteDetail(); break;
            }
        }

        void RenderHome()
        {
            var page = _ui.Begin(CanScan);
            HeaderCard(page, "어디다 버려?");
            if (CanScan)
            {
                var hint = _ui.Card(page, GuideUi.Paper, 10, 0);
                _ui.Label(hint, "물건 전체를 흰 테두리 안에 크게 맞춰 주세요.", 15, false,
                    GuideUi.Muted, TextAnchor.MiddleCenter);
                var space = GuideUi.NewRect("Camera View", page);
                GuideUi.Size(space, flexibleHeight: 1);
                var cameraActions = _ui.Card(page, GuideUi.Paper, 0, 4);
                _ui.Button(cameraActions, "쓰레기 스캔하기", StartScan, true, 52);
                var links = _ui.Row(cameraActions);
                var search = _ui.TextButton(links, "이름으로 찾기", () => ShowSearch(""), 44, 15);
                var notes = _ui.TextButton(links, "내 메모", ShowNotes, 44, 15);
                GuideUi.Size(search.transform, flexibleWidth: 1);
                GuideUi.Size(notes.transform, flexibleWidth: 1);
                _ui.ShowScanFrame();
                return;
            }
            var content = _ui.Scroll(page);
            var intro = _ui.Card(content, GuideUi.Paper, 0, 7);
            _ui.Label(intro, "분리배출 안내", 13, false, GuideUi.Muted);
            _ui.Label(intro, "무엇을 버릴까요?", 26, true);
            _ui.Label(intro, "물건 이름으로 배출 방법을 찾아보세요.",
                15, false, GuideUi.Muted);

            var frame = _ui.Card(content, GuideUi.Soft, 16, 8);
            GuideUi.Size(frame, height: 174);
            var mark = _ui.ScanMark(frame, 100);
            GuideUi.Size(mark, flexibleHeight: 1);
            _ui.Label(frame, "카메라 스캔은 아이폰·아이패드에서 사용할 수 있습니다.", 13, false,
                GuideUi.Muted, TextAnchor.MiddleCenter);

            var shortcuts = _ui.Card(content, GuideUi.Paper, 0, 0);
            _ui.Label(shortcuts, "자주 헷갈리는 물건", 14, true);
            _ui.Divider(shortcuts);
            _ui.ListButton(shortcuts, "배달 용기", "엽떡·마라탕 용기에 기름이 남았다면", () => ShowSearch("배달 용기"));
            _ui.ListButton(shortcuts, "페트병", "몸통·뚜껑·라벨 배출 방법", () => ShowSearch("페트병"));
            _ui.ListButton(shortcuts, "단추", "작은 생활용품의 재질 확인", () => ShowSearch("단추"));
            _ui.ListButton(shortcuts, "내 메모", "목록에 없는 물건과 확인할 내용", ShowNotes);
            var actions = _ui.Card(page, GuideUi.Paper, CanScan ? 12 : 0, 4);
            _ui.Button(actions, "쓰레기 스캔하기", StartScan, true, 52);
            _ui.TextButton(actions, "이름으로 직접 찾기", () => ShowSearch(""), 44, 15);
        }

        void HeaderCard(Transform parent, string title, Action back = null)
        {
            var card = _ui.Card(parent, GuideUi.Paper, 0, 0);
            _ui.Header(card, title, back);
        }

        void RenderSearch()
        {
            var page = _ui.Begin();
            _ui.Header(page, "물건 찾아보기", ShowHome);
            _ui.Label(page, "물건 이름을 입력하세요", 23, true);
            _ui.SearchField(page, _query, value => { _query = value; RenderSearchMatches(); });
            CategoryRow(page, new[] { "전체", "재활용", "음식물" });
            CategoryRow(page, new[] { "생활용품", "별도수거" });
            _searchResults = _ui.Scroll(page);
            RenderSearchMatches();
            _ui.TextButton(page, "목록에 없는 물건 메모하기", () => NewNote(_query));
        }

        void CategoryRow(Transform parent, string[] categories)
        {
            var row = _ui.Row(parent, 7);
            foreach (string category in categories)
            {
                var button = _ui.TextButton(row, category, () => { _category = category; RenderSearch(); }, 44, 13);
                button.GetComponentInChildren<Text>().color = _category == category ? GuideUi.Accent : GuideUi.Muted;
                if (_category != category) continue;
                var rule = GuideUi.NewRect("Selected Category", button.transform);
                rule.anchorMin = new Vector2(0, 0);
                rule.anchorMax = new Vector2(1, 0);
                rule.pivot = new Vector2(0.5f, 0);
                rule.sizeDelta = new Vector2(0, 2);
                rule.anchoredPosition = Vector2.zero;
                var image = rule.gameObject.AddComponent<Image>();
                image.color = GuideUi.Accent;
                image.raycastTarget = false;
            }
        }

        void RenderSearchMatches()
        {
            if (_page != Page.Search || _searchResults == null) return;
            GuideUi.Clear(_searchResults);
            var matches = _catalog.Search(_query).Where(MatchesCategory).ToArray();
            var personalMatches = _notes?.Search(_query).ToArray() ?? Array.Empty<PersonalWasteNote>();
            _ui.Label(_searchResults, "기본 안내 " + matches.Length + "개 품목", 13, false, GuideUi.Muted);
            foreach (var item in matches)
            {
                _ui.ListButton(_searchResults, item.name, null, () => SelectItem(item.id, true, false));
            }
            if (matches.Length == 0 && personalMatches.Length == 0)
            {
                var card = _ui.Card(_searchResults, GuideUi.Soft);
                bool hiddenByCategory = _catalog.Search(_query).Any();
                _ui.Label(card, hiddenByCategory ? "선택한 분류에는 결과가 없습니다" : "이 이름으로 찾지 못했습니다", 18, true);
                _ui.Label(card, hiddenByCategory ? "전체 분류에서 같은 이름의 품목을 확인하세요." :
                    "다른 이름으로 검색하거나 공식 품목사전을 확인하세요. 아직 없는 물건은 내 메모에 적어둘 수 있습니다.", 15, false, GuideUi.Muted);
                if (hiddenByCategory)
                    _ui.Button(card, "전체 분류에서 보기", () => { _category = "전체"; RenderSearch(); });
                AddOfficialLinks(card);
            }
            if (personalMatches.Length == 0) return;
            _ui.Divider(_searchResults);
            _ui.Label(_searchResults, "내 메모 " + personalMatches.Length + "개 · 직접 기록한 정보", 13, false, GuideUi.Muted);
            foreach (var note in personalMatches)
            {
                string id = note.id;
                _ui.ListButton(_searchResults, note.name, NoteStatus(note), () => ShowNote(id));
            }
        }

        bool MatchesCategory(WasteItem item)
        {
            string group = item.recognitionGroup ?? "other";
            switch (_category)
            {
                case "재활용": return new[] { "can", "bottle", "container", "paper", "glass" }.Contains(group);
                case "음식물": return group == "food";
                case "생활용품": return new[] { "small_item", "other", "clothing" }.Contains(group);
                case "별도수거": return new[] { "battery", "electronics", "lamp" }.Contains(group);
                default: return true;
            }
        }

        void RenderScanning()
        {
            var page = _ui.Begin();
            HeaderCard(page, "물건 스캔", ShowHome);
            var card = _ui.Card(page, GuideUi.Paper, 18, 14);
            GuideUi.Size(card, flexibleHeight: 1, minHeight: 200);
            _ui.Photo(card, _scanner.LatestCapturedFrame, 210);
            _ui.Label(card, "사진 확인 중", 23, true);
            _ui.Label(card, "잠시 기다려 주세요.", 15, false, GuideUi.Muted);
            _ui.TextButton(page, "취소", ShowHome);
        }

        void RenderCandidates()
        {
            var page = _ui.Begin();
            _ui.Header(page, "물건 확인", ShowHome);
            var content = _ui.Scroll(page);
            _ui.Photo(content, _scanner != null ? _scanner.LatestCapturedFrame : null, 175);
            _ui.Label(content, "어떤 물건인가요?", 24, true);
            _ui.Label(content, "촬영한 물건과 같은 항목을 선택하세요.", 15, false, GuideUi.Muted);
            foreach (var candidate in _candidates)
            {
                var selected = candidate.item;
                _ui.Choice(content, selected.name, () => SelectItem(selected.id, true, true));
            }
            _ui.Button(page, "맞는 항목 없음 · 이름으로 찾기", () => ShowSearch(""), false, 48, 15);
            _ui.TextButton(page, "다시 스캔하기", StartScan);
            _ui.TextButton(content, "목록에 없는 물건 메모하기", () => NewNote(""));
        }

        void RenderGuide()
        {
            if (CurrentItem == null || CurrentNode == null) { ShowSearch(); return; }
            var page = _ui.Begin();
            _ui.Header(page, CurrentNode.IsResult ? "배출 방법" : "상태 확인", BackFromGuide);
            var content = _ui.Scroll(page);
            if (CurrentNode.IsResult) RenderResult(content);
            else
            {
                _ui.Label(content, CurrentItem.name, 14, false, GuideUi.Muted);
                _ui.Label(content, CurrentNode.prompt, 24, true);
                _ui.Divider(content);
                foreach (var choice in CurrentNode.choices)
                {
                    var selected = choice;
                    _ui.Choice(content, selected.label, () => Choose(selected));
                }
            }
            if (!CurrentNode.IsResult && _history.Count > 0)
                _ui.TextButton(page, "이전 질문", BackFromGuide);
        }

        void RenderResult(Transform parent)
        {
            var result = CurrentNode.result;
            var lead = _ui.Card(parent, GuideUi.Paper, 0, 8);
            _ui.Label(lead, CurrentItem.name, 14, false, GuideUi.Muted);
            _ui.Label(lead, result.destination, 25, true, GuideUi.Accent);
            _ui.Label(lead, ScopeLabel(CurrentItem.sourceScope), 13, false, GuideUi.Muted);
            _ui.Divider(parent);
            _ui.Label(parent, "배출 전 준비", 18, true);
            for (int i = 0; i < result.steps.Length; i++)
            {
                var row = _ui.Row(parent, 12);
                var number = _ui.Label(row, (i + 1).ToString() + ".", 16, true, GuideUi.Muted);
                GuideUi.Size(number.transform, width: 21);
                var step = _ui.Label(row, result.steps[i], 17);
                GuideUi.Size(step.transform, flexibleWidth: 1);
            }
            if (!string.IsNullOrWhiteSpace(result.explanation))
            {
                var note = _ui.Card(parent, GuideUi.Soft, 14, 7);
                _ui.Label(note, "참고", 13, true);
                _ui.Label(note, result.explanation, 15, false, GuideUi.Muted);
            }
            if (CanScan && _spatial != null)
            {
                _ui.Button(parent, "공간에 안내 놓기", BeginPlacement, true);
                _ui.Label(parent, "책상이나 바닥을 비춘 뒤 안내판을 놓을 수 있습니다.", 13, false, GuideUi.Muted);
            }
            if (!string.IsNullOrEmpty(_notice))
                _ui.Label(parent, _notice, 14, true, GuideUi.Notice);
            var sources = _ui.Card(parent, GuideUi.Paper, 0, 6);
            _ui.Divider(sources);
            _ui.Label(sources, "참고 자료", 14, true);
            if (!string.IsNullOrWhiteSpace(CurrentItem.sourceCheckedOn))
                _ui.Label(sources, "확인 " + CurrentItem.sourceCheckedOn, 13, false, GuideUi.Muted);
            foreach (string url in result.sourceUrls.Distinct())
            {
                string source = url;
                _ui.TextButton(sources, SourceName(url) + "  ↗", () => Application.OpenURL(source));
            }
            if (CurrentItem.sourceScope != "seongbuk")
            {
                _ui.Label(sources, "배출 요일·수거 방식은 성북구 안내에서 확인해 주세요.", 13, false, GuideUi.Muted);
                _ui.TextButton(sources, "성북구 수거 안내  ↗", () => Application.OpenURL(
                    "https://www.sb.go.kr/www/selectBbsNttView.do?bbsNo=91&key=5927&nttNo=9502164"));
            }
            _ui.Button(parent, CanScan ? "다른 물건 스캔하기" : "다른 물건 찾아보기",
                () => { if (CanScan) StartScan(); else ShowSearch(""); }, !CanScan, 48, 15);
            _ui.TextButton(parent, "이 물건 처음부터 확인", () => SelectItem(CurrentItem.id, true, _cameFromScan));
        }

        void BeginPlacement()
        {
            _placementPlaced = false;
            Navigate(Page.Placement);
        }

        void PlaceGuide()
        {
            _placementPlaced = _spatial.TryPlace(CurrentNode.result, CurrentItem.name, out string message);
            _notice = message;
            Render();
        }

        void RenderPlacement()
        {
            var page = _ui.Begin(true);
            HeaderCard(page, "AR 안내", () => { _spatial.Clear(); Navigate(Page.Guide); });
            var clearCamera = GuideUi.NewRect("Camera View", page);
            GuideUi.Size(clearCamera, flexibleHeight: 1, minHeight: 60);
            if (!_placementPlaced)
            {
                var reticle = _ui.Label(clearCamera, "+", 30, false, Color.white, TextAnchor.MiddleCenter);
                GuideUi.Stretch(reticle.rectTransform);
            }
            var instructions = _ui.Card(page, GuideUi.Paper, 16, 8);
            _ui.Label(instructions, _placementPlaced ? "안내 배치 완료" : "책상이나 바닥을 비춰 주세요", 18, true);
            _ui.Label(instructions, _notice ?? "화면 가운데에 안내를 놓을 위치를 맞춰 주세요.", 14, false, GuideUi.Muted);
            _ui.Button(instructions, _placementPlaced ? "다른 위치에 놓기" : "이 위치에 안내 놓기", PlaceGuide, true);
            _ui.TextButton(instructions, "배출 방법으로 돌아가기", () => { _spatial.Clear(); Navigate(Page.Guide); });
        }

        void RenderMessage()
        {
            var page = _ui.Begin();
            _ui.Header(page, "어디다 버려?", ShowHome);
            var content = _ui.Scroll(page);
            _ui.Photo(content, _scanner != null ? _scanner.LatestCapturedFrame : null, 175);
            _ui.Label(content, _messageTitle, 24, true);
            _ui.Label(content, _messageBody, 17, false, GuideUi.Muted);
            AddOfficialLinks(content);
            _ui.Button(content, "목록에 없는 물건 메모하기", () => NewNote(""), false, 48, 15);
            _ui.Button(page, "이름으로 찾아보기", () => ShowSearch(""), true);
            if (CanScan) _ui.TextButton(page, "다시 스캔하기", StartScan);
        }

        void AddOfficialLinks(Transform parent)
        {
            _ui.TextButton(parent, "공식 품목사전 열기  ↗", () => Application.OpenURL(
                "https://www.wasteguide.or.kr/front/dischargeMethod/dictionary.do"));
            _ui.TextButton(parent, "성북구 수거 안내 확인  ↗", () => Application.OpenURL(
                "https://www.sb.go.kr/www/selectBbsNttView.do?bbsNo=91&key=5927&nttNo=9502164"));
        }

        void ShowNotes()
        {
            _confirmNoteDelete = false;
            Navigate(Page.Notes);
        }

        void NewNote(string name)
        {
            if (_notes == null) { ShowNotes(); return; }
            _noteDraft = new PersonalWasteNote { name = name ?? "" };
            Navigate(Page.NoteEdit);
        }

        void ShowNote(string id)
        {
            _selectedNoteId = id;
            _confirmNoteDelete = false;
            Navigate(Page.NoteDetail);
        }

        void RenderNotes()
        {
            var page = _ui.Begin();
            _ui.Header(page, "내 메모", ShowHome);
            if (_notes == null)
            {
                var error = _ui.Scroll(page);
                _ui.Label(error, _notesLoadError, 16);
                AddOfficialLinks(error);
                return;
            }
            _ui.Label(page, "직접 기록한 물건", 23, true);
            _ui.Label(page, "이 기기에 저장한 개인 기록입니다. 공식 배출 안내와 구분해서 확인하세요.", 14, false, GuideUi.Muted);
            _ui.SearchField(page, _noteQuery, value => { _noteQuery = value; RenderNoteMatches(); });
            _noteResults = _ui.Scroll(page);
            RenderNoteMatches();
            _ui.Button(page, "새 물건 메모하기", () => NewNote(_noteQuery), true);
        }

        void RenderNoteMatches()
        {
            if (_page != Page.Notes || _noteResults == null || _notes == null) return;
            GuideUi.Clear(_noteResults);
            var notes = _notes.Search(_noteQuery).ToArray();
            _ui.Label(_noteResults, notes.Length + "개 메모", 13, false, GuideUi.Muted);
            foreach (var note in notes)
            {
                string id = note.id;
                _ui.ListButton(_noteResults, note.name, NoteStatus(note), () => ShowNote(id));
            }
            if (notes.Length == 0)
                _ui.Label(_noteResults, "아직 저장한 물건이 없거나 검색어와 일치하는 메모가 없습니다. 이름만 적어두고 나중에 내용을 추가해도 됩니다.", 16, false, GuideUi.Muted);
        }

        void RenderNoteEdit()
        {
            if (_noteDraft == null || _notes == null) { ShowNotes(); return; }
            var page = _ui.Begin();
            _ui.Header(page, "물건 메모하기", () =>
            {
                if (string.IsNullOrEmpty(_noteDraft.id)) ShowNotes();
                else ShowNote(_noteDraft.id);
            });
            var content = _ui.Scroll(page);
            _ui.Label(content, "목록에 없는 물건 기록", 23, true);
            _ui.Label(content, "이름만 먼저 저장할 수 있습니다. 확인한 배출 방법과 출처는 나중에 수정하세요.", 14, false, GuideUi.Muted);
            _noteFormError = _ui.Label(content, "", 14, true, GuideUi.Notice);
            _ui.Label(content, "물건 이름 · 필수", 14, true);
            _ui.TextField(content, _noteDraft.name, "예: 접이식 우산", value => _noteDraft.name = value, 60);
            _ui.Label(content, "재질·상태 · 선택", 14, true);
            _ui.TextField(content, _noteDraft.material, "예: 천과 금속이 붙어 있음", value => _noteDraft.material = value, 120);
            _ui.Label(content, "확인할 내용·배출 방법 메모 · 선택", 14, true);
            _ui.TextField(content, _noteDraft.disposalMemo, "모르면 비워두거나 나중에 확인할 내용을 적으세요.",
                value => _noteDraft.disposalMemo = value, 1000, true);
            _ui.Label(content, "참고 링크 · 선택", 14, true);
            _ui.TextField(content, _noteDraft.sourceUrl, "https://로 시작하는 자료 주소", value => _noteDraft.sourceUrl = value, 500);
            AddOfficialLinks(content);
            _ui.Label(content, "메모는 이 기기에만 저장됩니다. 기본 안내 목록이나 사진 인식 학습에는 자동으로 반영되지 않습니다. 앱을 삭제하면 기록도 사라질 수 있습니다.", 13, false, GuideUi.Muted);
            _ui.Button(page, "이 기기에 저장", SaveNote, true);
        }

        void SaveNote()
        {
            GuideUi.DismissKeyboard();
            try
            {
                var staged = new PersonalWasteNotes(_notes.Data);
                var saved = staged.Upsert(_noteDraft);
                PersonalWasteNoteStore.Save(staged.Data);
                _notes = staged;
                ShowNote(saved.id);
            }
            catch (Exception exception)
            {
                if (_noteFormError != null)
                {
                    _noteFormError.text = exception is ArgumentException ? exception.Message :
                        "메모를 저장하지 못했습니다. 입력 분량과 기기 저장 공간을 확인하세요.";
                    Canvas.ForceUpdateCanvases();
                    var scroll = _noteFormError.GetComponentInParent<ScrollRect>();
                    if (scroll != null) scroll.verticalNormalizedPosition = 1;
                }
                Debug.LogWarning("Personal waste note save failed: " + exception.Message);
            }
        }

        void RenderNoteDetail()
        {
            var note = _notes?.Find(_selectedNoteId);
            if (note == null) { ShowNotes(); return; }
            var page = _ui.Begin();
            _ui.Header(page, "저장한 메모", ShowNotes);
            var content = _ui.Scroll(page);
            _ui.Label(content, "개인 메모 · 검증되지 않은 정보", 13, true, GuideUi.Muted);
            _ui.Label(content, note.name, 25, true);
            _ui.Label(content, NoteStatus(note), 14, false, GuideUi.Muted);
            _ui.Divider(content);
            if (!string.IsNullOrWhiteSpace(note.material))
            {
                _ui.Label(content, "재질·상태", 14, true);
                _ui.Label(content, note.material, 16);
            }
            _ui.Label(content, "내가 적은 내용", 14, true);
            _ui.Label(content, string.IsNullOrWhiteSpace(note.disposalMemo) ?
                "배출 방법을 아직 기록하지 않았습니다. 공식 안내를 확인한 뒤 메모를 수정하세요." : note.disposalMemo, 16);
            if (!string.IsNullOrWhiteSpace(note.sourceUrl))
                _ui.TextButton(content, "기록한 참고 링크 열기  ↗", () => Application.OpenURL(note.sourceUrl));
            if (DateTime.TryParse(note.updatedUtc, null, System.Globalization.DateTimeStyles.RoundtripKind, out DateTime updated))
                _ui.Label(content, "저장 " + updated.ToLocalTime().ToString("yyyy.MM.dd HH:mm"), 13, false, GuideUi.Muted);
            AddOfficialLinks(content);
            var actions = _ui.Card(page, GuideUi.Paper, 0, 4);
            if (!string.IsNullOrEmpty(_notice)) _ui.Label(actions, _notice, 14, true, GuideUi.Notice);
            if (_confirmNoteDelete)
            {
                _ui.Label(actions, "이 메모를 삭제할까요?", 16, true);
                _ui.Button(actions, "삭제", DeleteNote, true, 48);
                _ui.TextButton(actions, "취소", () => { _confirmNoteDelete = false; Render(); });
            }
            else
            {
                _ui.Button(actions, "메모 수정", () => { _noteDraft = _notes.Find(note.id); Navigate(Page.NoteEdit); }, true);
                _ui.TextButton(actions, "메모 삭제", () => { _confirmNoteDelete = true; Render(); });
            }
        }

        void DeleteNote()
        {
            try
            {
                var staged = new PersonalWasteNotes(_notes.Data);
                staged.Remove(_selectedNoteId);
                PersonalWasteNoteStore.Save(staged.Data);
                _notes = staged;
                ShowNotes();
            }
            catch (Exception exception)
            {
                _notice = "메모를 삭제하지 못했습니다. 저장 공간을 확인하고 다시 시도하세요.";
                Debug.LogWarning("Personal waste note delete failed: " + exception.Message);
                Render();
            }
        }

        static string NoteStatus(PersonalWasteNote note) =>
            string.IsNullOrWhiteSpace(note.disposalMemo) ? "배출 방법 확인 필요" : "내가 작성한 메모 · 공식 안내 아님";

        static string ScopeLabel(string scope)
        {
            switch (scope)
            {
                case "seongbuk": return "성북구 안내 기준";
                case "seoul": return "서울시 안내 참고";
                case "seoul_other_district_reference": return "다른 자치구 참고 사례 · 성북구 기준 확인 필요";
                case "national": return "전국 공통 안내 · 지역 수거 방식 확인 필요";
                default: return "공식 품목 안내 · 지역 수거 방식 확인 필요";
            }
        }

        static string SourceName(string url)
        {
            if (url.Contains("wasteguide.or.kr")) return "분리의정석";
            if (url.Contains("sb.go.kr")) return "성북구청";
            if (url.Contains("seoul.go.kr")) return "서울시";
            return "공식 배출 안내";
        }
    }
}
